fn shout(text: String) {
    println!("{}!", text);
}

fn main() {
    let word = String::from("owned");
    shout(word);
    println!("then reused");
    println!("{word}");
}

exercise.solution:
fn shout(text: &str) {
    println!("{text}!");
}

fn main() {
    let word = String::from("owned");
    shout(&word);
    println!("then reused");
    println!("{word}");
}
